BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-34','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考兒童及少年性交易防制條例第18條：考試時規定法院認兒童或少年有從事性交易者，除法定例外情形外，應裁定將其安置於中途學校，施予二年之特殊教育。該條例已於 2015-02-04 修正名稱為兒童及少年性剝削防制條例並修正全文（2017-01-01 施行），現行條文已無「安置於中途學校施予二年特殊教育」之規定；現行第19條改為法院認有安置必要者，裁定安置於兒童及少年福利機構、寄養家庭、中途學校或其他適當之醫療、教育機構，期間不得逾二年。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP104-2-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考兒童及少年性剝削防制條例第15條（查獲救援後二十四小時內交主管機關）、第16條（緊急安置七十二小時內評估）及第19條（法院於事證調查完竣後七日內裁定）。考試時之條文為 2015-02-04 修正公布（2017-01-01 施行）之條文；第16條考試日後未再修正；第15條、第19條於 2018-01-03 修正（2018-07-01 施行），二十四小時及七日內裁定之規定未變，第19條並刪除「對被害人施予六個月以上二年以下之輔導」，選項(D)於考試時及現行規定下均不正確，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP105-2-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考兒童及少年性剝削防制條例第15條（二十四小時內交主管機關）、第18條（安置後四十五日內提出審前報告）、第21條（每三個月進行評估）及第29條（親職教育輔導八小時以上五十小時以下）。考試時之條文為 2015-02-04 修正公布（2017-01-01 施行）之條文；第18條、第29條考試日後未再修正；第15條、第21條於 2018-01-03 修正（2018-07-01 施行），二十四小時及每三個月評估之規定未變，選項(A)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP106-2-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第16條（法院認有繼續安置必要者，安置期間不得逾三個月），最後修正公布日：第16條 2015-02-04（全文修正），本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP106-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考兒童及少年性剝削防制條例第15條（查獲及救援被害人後二十四小時內交主管機關）。第15條於 2018-01-03 修正（2018-07-01 施行），增訂列為保護個案者之處置及未列保護個案者之轉介，二十四小時之規定未變，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP107-1-08','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考兒童及少年性剝削防制條例第15條（查獲救援後二十四小時內交主管機關）、第16條（緊急安置七十二小時內評估）、第18條（安置後四十五日內提出審前報告）及本條例名稱（2015-02-04 由兒童及少年性交易防制條例修正為現名）。第16條、第18條考試日後未再修正；第15條於 2018-01-03 修正公布、考試後之 2018-07-01 施行，二十四小時之規定未變，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP107-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第18條（主管機關應於被害人安置後四十五日內提出審前報告並聲請法院裁定），最後修正公布日：第18條 2015-02-04（全文修正），本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP107-2-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考兒童及少年性剝削防制條例第7條（報告義務人）。考試時之條文（2018-01-03 修正、2018-07-01 施行）已列入移民業務機構從業人員、保育人員及資訊休閒業從業人員；第7條於 2023-02-15 修正，改為於執行職務或業務時知有被害人應即通報、至遲不得超過二十四小時，並增列公寓大廈管理服務人員，圖書出版業從業人員仍非通報義務人，選項(D)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP108-1-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第15條（查獲及救援被害人後二十四小時內交由主管機關，列為保護個案者得送交適當場所緊急安置），最後修正公布日：第15條 2018-01-03，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP108-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考兒童及少年性剝削防制條例第7條（報告義務人）。第7條於 2023-02-15 修正，改為於執行職務或業務時知有被害人應即通報、至遲不得超過二十四小時，並增列公寓大廈管理服務人員；觀光業從業人員仍為通報義務人，便利商店店長、公益彩券經銷商及新聞記者仍非，選項(B)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP109-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第20條（對法院裁定不服者得於裁定送達後十日內提起抗告），最後修正公布日：第20條 2015-02-04（全文修正），本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP109-2-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第10條（被害人受詢（訊）問時社會工作人員等得陪同在場並陳述意見），最後修正公布日：第10條 2015-02-04（全文修正），本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP109-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考兒童及少年性剝削防制條例第22條（中途學校）。第22條於 2023-02-15 修正公布為「中途學校之組織及其教育之實施，另以法律定之」，惟依第55條該條施行日期由行政院定之，迄今尚未施行（全國法規資料庫標示部分條文尚未生效），現行有效者仍為考試時條文（中途學校之設立準用少年矯正學校設置及教育實施通則、員額編制準則由中央教育主管機關會同中央主管機關定之、聘請社會工作等專業人員提供選替教育及輔導、學生學籍分散設於普通學校並由該普通學校發給畢業證書、逾國民教育階段者得提供繼續教育）；修正條文施行後，中途學校之組織及教育應依另定之法律。選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP110-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考兒童及少年性剝削防制條例第22條（中途學校）。第22條於 2023-02-15 修正公布為「中途學校之組織及其教育之實施，另以法律定之」，惟依第55條該條施行日期由行政院定之，迄今尚未施行（全國法規資料庫標示部分條文尚未生效），現行有效者仍為考試時條文（中途學校之設立準用少年矯正學校設置及教育實施通則、員額編制準則由中央教育主管機關會同中央主管機關定之、聘請社會工作等專業人員提供選替教育及輔導、學生學籍分散設於普通學校並由該普通學校發給畢業證書、逾國民教育階段者得提供繼續教育）；修正條文施行後，中途學校之組織及教育應依另定之法律。選項(D)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP110-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第10條（被害人受詢（訊）問時得陪同在場之人），最後修正公布日：第10條 2015-02-04（全文修正），本題考試日 2021-08-21 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP111-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第15條、第16條、第26條、第29條（查獲救援後二十四小時內交主管機關、緊急安置七十二小時內評估、無另犯其他之罪不適用少年事件處理法及社會秩序維護法、親職教育輔導八小時以上五十小時以下），最後修正公布日：第15條 2018-01-03、第16條 2015-02-04（全文修正）、第26條 2015-02-04（全文修正）、第29條 2015-02-04（全文修正），本題考試日 2022-02-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP111-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考兒童及少年性剝削防制條例第22條（中途學校）。第22條於 2023-02-15 修正公布為「中途學校之組織及其教育之實施，另以法律定之」，惟依第55條該條施行日期由行政院定之，迄今尚未施行（全國法規資料庫標示部分條文尚未生效），現行有效者仍為考試時條文（中途學校之設立準用少年矯正學校設置及教育實施通則、員額編制準則由中央教育主管機關會同中央主管機關定之、聘請社會工作等專業人員提供選替教育及輔導、學生學籍分散設於普通學校並由該普通學校發給畢業證書、逾國民教育階段者得提供繼續教育）；修正條文施行後，中途學校之組織及教育應依另定之法律。選項(A)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP111-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第26條（無另犯其他之罪不適用少年事件處理法及社會秩序維護法；另犯其他之罪應先移送主管機關處理後再移送少年法院（庭）），最後修正公布日：第26條 2015-02-04（全文修正），本題考試日 2022-07-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP112-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第19條（法院於事證調查完竣後七日內之裁定，無合法停（居）留許可者不付安置並於遣返前續予輔導），最後修正公布日：第19條 2018-01-03，本題考試日 2023-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP113-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第15條、第16條、第18條（查獲救援後二十四小時內交主管機關、緊急安置七十二小時內評估及繼續安置不得逾三個月、安置後四十五日內提出審前報告），最後修正公布日：第15條 2018-01-03、第16條 2015-02-04（全文修正）、第18條 2015-02-04（全文修正），本題考試日 2024-07-27 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP114-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年性剝削防制條例第2條（兒童或少年性剝削之定義），最後修正公布日：第2條 2024-08-07，本題考試日 2025-02-08 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023'),('SP114-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-07-26。本題考兒童及少年性剝削防制條例第7條（通報義務及通報人身分保密）、第8條（犯罪網頁資料與嫌疑人個人資料及網路使用紀錄保留一百八十日）及第10條（社會工作人員得陪同在場）。第7條、第10條考試日後未再修正；第8條於 2024-08-07 修正，惟依第55條該條施行日期由行政院定之，迄今尚未施行，現行有效者仍為考試時之 2023-02-15 修正條文，且修正前後均規定保留一百八十日，選項(D)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050023');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>22 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>22 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'5c1faf5a6849faae6310e73c5acc6fbb' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_21, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) total_22 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
